CREATE VIRTUAL TABLE t1 USING fts3(a); WITH RECURSIVE n(i) AS (VALUES(1) UNION ALL SELECT i+1 FROM n WHERE i<31) INSERT INTO t1(rowid,a) SELECT i, trim(CASE WHEN (i & 1)!=0 THEN 'one ' ELSE '' END || CASE WHEN (i & 2)!=0 THEN 'two ' ELSE '' END || CASE WHEN (i & 4)!=0 THEN 'three ' ELSE '' END || CASE WHEN (i & 8)!=0 THEN 'four ' ELSE '' END || CASE WHEN (i & 16)!=0 THEN 'five ' ELSE '' END) FROM n;